#![cfg(feature="test-hook")]
use atlas_sqlcipher_proof::Vault;use std::{fs,process::{Command,Stdio},thread,time::{Duration,Instant}};
#[test]fn open_child(){let Ok(root)=std::env::var("ATLAS_TEST_RACE_ROOT")else{return};let source=std::path::Path::new(&root).join("source.db");let result=Vault::open(&source,"test-password");assert!(result.is_err(),"SQLite opened replaced file while retained fd pointed to original");}
#[test]fn path_swap_between_fd_and_sqlite_then_restore_is_rejected(){let root=std::env::temp_dir().join(format!("atlas-open-race-{}",uuid::Uuid::new_v4()));fs::create_dir(&root).unwrap();let source=root.join("source.db");let old=root.join("original.db");let replacement=root.join("replacement.db");let barrier=root.join("barrier");fs::create_dir(&barrier).unwrap();let mut v=Vault::create(&source,"test-password").unwrap();v.put_note("id","title","OriginalUnique48917").unwrap();drop(v);fs::copy(&source,&replacement).unwrap();let mut v=Vault::open(&replacement,"test-password").unwrap();v.put_note("id","title","ReplacementUnique48917").unwrap();drop(v);let mut child=Command::new(std::env::current_exe().unwrap()).args(["--exact","open_child","--nocapture"]).env("ATLAS_TEST_RACE_ROOT",&root).env("ATLAS_TEST_VAULT_OPEN_BARRIER_DIR",&barrier).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let wait=|name:&str,child:&mut std::process::Child|{let until=Instant::now()+Duration::from_secs(8);while !barrier.join(name).exists(){assert!(child.try_wait().unwrap().is_none(),"child exited before {name}");assert!(Instant::now()<until,"barrier {name} timed out");thread::sleep(Duration::from_millis(10));}};wait("fd-ready",&mut child);fs::rename(&source,&old).unwrap();fs::rename(&replacement,&source).unwrap();fs::write(barrier.join("fd-resume"),b"go").unwrap();wait("sqlite-ready",&mut child);fs::rename(&source,&replacement).unwrap();fs::rename(&old,&source).unwrap();fs::write(barrier.join("sqlite-resume"),b"go").unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));assert_eq!(Vault::open(&source,"test-password").unwrap().get_note("id").unwrap(),"OriginalUnique48917");assert_eq!(Vault::open(&replacement,"test-password").unwrap().get_note("id").unwrap(),"ReplacementUnique48917");fs::remove_dir_all(root).unwrap();}
